<script setup lang="ts">withDefaults(defineProps<{state:'loading'|'empty'|'error'|'success';title?:string;description?:string;actionLabel?:string}>(),{});const emit=defineEmits<{action:[]}>()</script><template><section class="vx-status-state" :role="state==='error'?'alert':'status'"><span class="vx-status-state__icon" aria-hidden="true">{{state==='loading'?'◌':state==='error'?'!':state==='success'?'✓':'○'}}</span><h3>{{title||({loading:'Loading',empty:'Nothing here yet',error:'Something went wrong',success:'Complete'}[state])}}</h3><p v-if="description">{{description}}</p><button v-if="actionLabel" type="button" class="vx-button" @click="emit('action')">{{actionLabel}}</button></section></template>
